package com.autocare.platform.order;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.Path;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import static org.junit.jupiter.api.Assertions.*;

/** Actual MySQL/license lifecycle, explicitly synthetic vectors; no semantic model evidence. */
class JdbcKnowledgeVectorIndexTest extends JdbcLicensedKnowledgeTest {
 KnowledgeVectorIndex index;EmbeddingProfile profile;EmbeddingProvider provider;
 @BeforeEach void vectorSetup(){profile=EmbeddingFoundationTest.profile();provider=(p,texts)->{
  assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());
  return new EmbeddingProvider.Output(p.fingerprint(),texts.stream().map(t->t.contains("刹车")||t.contains("制动")?new double[]{1,0,0}:new double[]{0,1,0}).toList());
 };index=new KnowledgeVectorIndex(db,knowledge,profile,provider,true);}
 @AfterEach void vectorClose(){index.close();}
 ObjectNode allowed(){return config().put("embedding_allowed",true).put("embedding_policy_version",KnowledgeInput.EMBEDDING_POLICY);}
 long published(ObjectNode body){long id=createKnowledge(body);publishKnowledge(id);return id;}
 String jobState(long id){return jdbc.queryForObject("SELECT state FROM knowledge_embedding_job WHERE id=?",String.class,id);}
 @Test void legacyPayloadRemainsUnchangedAndCannotImplyEmbeddingPermission(){var old=config();long id=published(old);assertEquals(old,db.parse(jdbc.queryForObject("SELECT payload FROM knowledge_document WHERE id=?",String.class,id)));assertEquals(404,code(()->index.enqueue(id)));assertEquals("KEYWORD",knowledge.search(owner,1,"冷却液",null).get("method"));assertEquals(0,count("knowledge_embedding_job"));}
 @Test void independentPermissionPairIsStrictAndAudited(){for(ObjectNode body:List.of(config().put("embedding_allowed",true),config().put("embedding_policy_version",KnowledgeInput.EMBEDDING_POLICY),allowed().put("embedding_allowed","true"),allowed().put("embedding_policy_version","OLD")))assertEquals(400,code(()->KnowledgeInput.config(body.toString(),false)));long id=published(allowed().put("embedding_allowed",false));assertEquals(404,code(()->index.enqueue(id)));assertEquals(403,code(()->knowledge.save(first,null,key(),allowed())));assertTrue(jdbc.queryForObject("SELECT payload FROM knowledge_document WHERE id=?",String.class,id).contains("embedding_allowed"));}
 @Test void durableTaskIsIdempotentAndRetainsCompleteBoundChunks(){long document=published(allowed().put("body","合成制动资料😀".repeat(80)));long job=index.enqueue(document);assertEquals(job,index.enqueue(document));int audit=count("audit_log");assertTrue(index.workOne());assertEquals("SUCCEEDED",jobState(job));assertFalse(index.workOne());assertEquals(audit,count("audit_log"));var chunks=KnowledgeChunks.split(db.parse(jdbc.queryForObject("SELECT payload FROM knowledge_document WHERE id=?",String.class,document)).path("body").asText());assertEquals(chunks.size(),count("knowledge_embedding_chunk"));assertEquals(job,index.enqueue(document));}
 @Test void exactCosineRankingIsScopedAndDoesNotReplaceKeywordSearch(){long first=published(allowed()),second=published(allowed().put("title","合成制动参考").put("body","合成制动资料"));index.enqueue(first);index.enqueue(second);assertTrue(index.workOne());assertTrue(index.workOne());var hits=index.rank(owner,1,"刹车",5);assertEquals(second,hits.get(0).documentId());assertEquals(1,hits.get(0).score(),1e-12);assertEquals(first,hits.get(1).documentId());assertEquals(0,hits.get(1).score(),1e-12);assertEquals(404,code(()->index.rank(owner,2,"刹车",5)));assertEquals("KEYWORD",knowledge.search(owner,1,"制动",null).get("method"));}
 @Test void stoppedOrExpiredSourceIsImmediatelyHiddenBeforeCleanup(){long document=published(allowed());long job=index.enqueue(document);index.workOne();knowledge.status(manager,document,key(),state(2,"STOPPED"));assertTrue(index.rank(owner,1,"冷却液",5).isEmpty());assertTrue(count("knowledge_embedding_chunk")>0);index.cleanup();assertEquals("CANCELLED",jobState(job));assertEquals(0,count("knowledge_embedding_chunk"));}
 @Test void revokeDuringProviderCallWithholdsEveryPartialVector(){long document=published(allowed().put("body","合成冷却液".repeat(300)));long job=index.enqueue(document);try(var other=new KnowledgeVectorIndex(db,knowledge,profile,(p,texts)->{knowledge.status(manager,document,key(),state(2,"STOPPED"));return new EmbeddingProvider.Output(p.fingerprint(),texts.stream().map(t->new double[]{1,0,0}).toList());},true)){assertTrue(other.workOne());assertEquals("CANCELLED",jobState(job));assertEquals(0,count("knowledge_embedding_chunk"));}}
 @Test void invalidVectorsFailSafelyWithoutRetryOrTextInMetadata(){long job=index.enqueue(published(allowed()));try(var other=new KnowledgeVectorIndex(db,knowledge,profile,(p,t)->new EmbeddingProvider.Output(p.fingerprint(),List.of(new double[]{0,0,0})),true)){other.workOne();assertEquals("FAILED",jobState(job));assertEquals("INVALID_VECTOR",jdbc.queryForObject("SELECT error_code FROM knowledge_embedding_job WHERE id=?",String.class,job));assertFalse(other.workOne());assertEquals(0,count("knowledge_embedding_chunk"));assertFalse(jdbc.queryForList("SELECT * FROM knowledge_embedding_job").toString().contains("冷却液"));}}
 @Test void leaseLossAndDisabledCleanupCannotBeOverwritten(){long job=index.enqueue(published(allowed()));try(var other=new KnowledgeVectorIndex(db,knowledge,profile,(p,t)->{clock.value=clock.value.plusSeconds(181);return new EmbeddingProvider.Output(p.fingerprint(),List.of(new double[]{1,0,0}));},true)){other.workOne();assertEquals("FAILED",jobState(job));assertEquals("WORKER_LOST",jdbc.queryForObject("SELECT error_code FROM knowledge_embedding_job WHERE id=?",String.class,job));}long second=index.enqueue(published(allowed()));try(var disabled=new KnowledgeVectorIndex(db,knowledge,profile,provider,false)){assertFalse(disabled.workOne());assertEquals(503,code(()->disabled.rank(owner,1,"冷却液",5)));disabled.cleanup();assertEquals("CANCELLED",jobState(second));}}
 @Test void modelAndProfileChangeNeverMixIndexes(){long document=published(allowed());index.enqueue(document);index.workOne();var otherProfile=new EmbeddingProfile(profile.model(),"b".repeat(40),3,profile.queryPrefix());try(var other=new KnowledgeVectorIndex(db,knowledge,otherProfile,provider,true)){assertTrue(other.rank(owner,1,"冷却液",5).isEmpty());assertTrue(other.enqueue(document)>0);}jdbc.update("UPDATE model SET status=0 WHERE id=1");assertTrue(index.rank(owner,1,"冷却液",5).isEmpty());}
 @Test void tamperedStoredSourceChunkOrVectorCannotBecomeReference(){long document=published(allowed());long job=index.enqueue(document);index.workOne();jdbc.update("UPDATE knowledge_embedding_chunk SET chunk_hash=? WHERE job_id=?","b".repeat(64),job);assertEquals(503,code(()->index.rank(owner,1,"冷却液",5)));jdbc.update("UPDATE knowledge_document SET payload=JSON_SET(payload,'$.embedding_allowed',false) WHERE id=?",document);assertTrue(index.rank(owner,1,"冷却液",5).isEmpty());}
 @Test void revokedOwnerAfterQueryEmbeddingNeverReceivesIndexHits(){long document=published(allowed());index.enqueue(document);index.workOne();try(var other=new KnowledgeVectorIndex(db,knowledge,profile,(p,t)->{jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());return provider.embed(p,t);},true)){assertEquals(401,code(()->other.rank(owner,1,"冷却液",5)));}}
 @Test void repeatMigrationPreservesRowsAndDatabaseRejectsInconsistentVectors()throws Exception{long document=published(allowed());long job=index.enqueue(document);index.workOne();try(var c=jdbc.getDataSource().getConnection()){ScriptUtils.executeSqlScript(c,new FileSystemResource(Path.of("..","docs/sql/migrations/V065__knowledge_embedding_index.sql")));}assertEquals("SUCCEEDED",jobState(job));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE knowledge_embedding_chunk SET dimension=4 WHERE job_id=?",job));}
 @Test void missingAllChunksOrOneChunkNeverClaimsACompleteRank(){for(boolean all:List.of(false,true)){long document=published(allowed().put("body","合成制动".repeat(200)));long job=index.enqueue(document);index.workOne();jdbc.update("DELETE FROM knowledge_embedding_chunk WHERE job_id=?"+(all?"":" AND ordinal=0"),job);assertEquals(503,code(()->index.rank(owner,1,"刹车",5)));knowledge.status(manager,document,key(),state(2,"STOPPED"));index.cleanup();}}
 @Test void aLaterInvalidBatchLeavesNoPartialIndex(){long job=index.enqueue(published(allowed().put("body","合成制动".repeat(1000))));var calls=new AtomicInteger();try(var other=new KnowledgeVectorIndex(db,knowledge,profile,(p,t)->calls.incrementAndGet()==1?provider.embed(p,t):new EmbeddingProvider.Output(p.fingerprint(),List.of()),true)){other.workOne();assertEquals(2,calls.get());assertEquals("FAILED",jobState(job));assertEquals(0,count("knowledge_embedding_chunk"));}}
 @Test void expiryAndAuditTamperingInvalidateAlreadySucceededIndex(){long document=published(allowed());long job=index.enqueue(document);index.workOne();clock.value=clock.value.plusSeconds(3601);assertTrue(index.rank(owner,1,"冷却液",5).isEmpty());index.cleanup();assertEquals(0,count("knowledge_embedding_chunk"));assertEquals("CANCELLED",jobState(job));}
 @Test void staleLeaseCannotOverwriteTheCurrentWorkerToken(){long job=index.enqueue(published(allowed()));try(var other=new KnowledgeVectorIndex(db,knowledge,profile,(p,t)->{jdbc.update("UPDATE knowledge_embedding_job SET lease_token=? WHERE id=?",key(),job);return provider.embed(p,t);},true)){other.workOne();assertEquals("RUNNING",jobState(job));assertEquals(0,count("knowledge_embedding_chunk"));clock.value=clock.value.plusSeconds(181);index.cleanup();assertEquals("FAILED",jobState(job));assertFalse(index.workOne());}}
 @Test void concurrentInstancesEnqueueOneJobAndNeverBothClaimIt()throws Exception{
  long document=published(allowed());try(var other=new KnowledgeVectorIndex(db,knowledge,profile,provider,true)){
   var a=java.util.concurrent.CompletableFuture.supplyAsync(()->index.enqueue(document));var b=java.util.concurrent.CompletableFuture.supplyAsync(()->other.enqueue(document));assertEquals(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals(1,count("knowledge_embedding_job"));
   var ready=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);
   try(var blocked=new KnowledgeVectorIndex(db,knowledge,profile,(p,t)->{ready.countDown();try{assertTrue(release.await(5,java.util.concurrent.TimeUnit.SECONDS));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException();}return provider.embed(p,t);},true)){
    var running=java.util.concurrent.CompletableFuture.supplyAsync(blocked::workOne);assertTrue(ready.await(5,java.util.concurrent.TimeUnit.SECONDS));assertFalse(other.workOne());release.countDown();assertTrue(running.get(10,java.util.concurrent.TimeUnit.SECONDS));
   }finally{release.countDown();}
  }
 }
 @Test void oversizedExactScanFailsInsteadOfSilentlyReturningTheFirst512Blocks(){for(int i=0;i<12;i++){index.enqueue(published(allowed().put("body","x".repeat(10000))));assertTrue(index.workOne());}assertTrue(count("knowledge_embedding_chunk")>512);assertEquals(503,code(()->index.rank(owner,1,"冷却液",5)));}
 @Test void tiedScoresHaveStableDocumentAndChunkOrder(){long first=published(allowed().put("body","制动".repeat(300))),second=published(allowed().put("body","制动".repeat(300)));index.enqueue(first);index.enqueue(second);index.workOne();index.workOne();var hits=index.rank(owner,1,"刹车",5);assertEquals(List.of(second,first),hits.stream().map(KnowledgeVectorIndex.Hit::documentId).toList());assertTrue(hits.stream().allMatch(h->h.ordinal()==0));}
}
